import datetime
import json
import os
from pathlib import Path
import signal
import sys
import time
import traceback
import uuid

ROOT = Path('/home/r/dev/minor/stackd')
sys.path.insert(0, str(ROOT / 'scripts/aws'))
from aws_cli import observe

ACCOUNT = '000000000000'
REGION = 'us-east-1'
PREFIX = 'stackd-sns-archive-cold-' + uuid.uuid4().hex[:10]
OUTPUT = ROOT / 'testdata/aws/sns/archive_kms_cold.json'
ENV = {k: v for k, v in os.environ.items() if not k.startswith('AWS_ENDPOINT_URL')}
ENV.update(AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_MAX_ATTEMPTS='1', AWS_PAGER='')
T0 = time.monotonic()
STOP = False
CASES = []
QUEUES = []
SUBS = []

def stamp():
    return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00', 'Z')

DATA = {'account': ACCOUNT, 'region': REGION, 'prefix': PREFIX, 'started': stamp(), 'observations': [], 'receipts': [], 'windows': [], 'cleanup': [], 'cases': CASES,
        'sources': ['https://docs.aws.amazon.com/sns/latest/dg/message-archiving-and-replay-topic-owner.html#message-archiving-and-replay-topic-kms'],
        'documented_contract': 'The topic-owner guide requires an SNS service-principal kms:Decrypt and kms:GenerateDataKey Allow on the historical key, retaining existing grants; disabled/deleted keys or incorrectly configured policy prevent replay.',
        'experiment_design': 'Two isolated encrypted FIFO archives: documented Allow baseline, and fresh topic/key with explicit unconditional sns.amazonaws.com kms:Decrypt Deny before first publication. Owner/publisher root grant always intact. Fresh standard SQS queues avoid FIFO deduplication. Observe warm and eight-minute denied replays, disable original keys until twenty-minute replay, restore keys/grants and replay original publication, then collect propagated CloudTrail. Elapsed time alone never establishes a cache miss.',
        'limitations': ['A receive-window absence is not a native Failed status or universal timeout.', 'Fresh queues and subscriptions do not establish a fresh SNS archive cache.', 'CloudTrail event history is eventually consistent; event absence does not prove no KMS call.', 'No functions, roles or log groups are created; only topics, subscriptions, queues and two customer-managed keys.', 'Customer-managed keys remain PendingDeletion for the native minimum seven-day window.']}

def save():
    DATA['updated'] = stamp()
    OUTPUT.write_text(json.dumps(DATA, indent=2) + '\n')

def redact(value):
    if isinstance(value, dict):
        return {k: ('[REDACTED]' if k.lower() in ('accesskeyid', 'secretaccesskey', 'sessiontoken', 'confirmationtoken') else redact(v)) for k,v in value.items()}
    if isinstance(value, list):
        return [redact(v) for v in value]
    return value

def call(label, service, operation, parameters=None, strict=True, cleanup=False, paginate=False):
    begun = stamp()
    result = observe(service, operation, parameters or {}, ENV, paginate=paginate)
    if service == 'cloudtrail':
        for event in result.get('output', {}).get('Events', []):
            event['CloudTrailEvent'] = json.dumps(redact(json.loads(event['CloudTrailEvent'])))
    row = {'label': label, 'service': service, 'operation': operation, 'input': parameters or {}, 'result': result, 'started': begun, 'observed': stamp()}
    DATA['cleanup' if cleanup else 'observations'].append(row)
    save()
    if strict and result['code'] != 'Success':
        raise RuntimeError(label + ': ' + json.dumps(result))
    return result.get('output', {})

def stop(signum, frame):
    global STOP
    STOP = True
signal.signal(signal.SIGINT, stop)
signal.signal(signal.SIGTERM, stop)

def check():
    if STOP or time.monotonic() - T0 > 1800:
        raise RuntimeError('Experiment stop/deadline; reserving cleanup time')

def until(seconds, label):
    start = stamp()
    while time.monotonic() - T0 < seconds:
        check()
        time.sleep(1)
    DATA['windows'].append({'label': label, 'start': start, 'end': stamp(), 'kind': 'idle; not evidence of cold cache'})
    save()

def policy(denied):
    rows = [{'Sid': 'OwnerPublisherUnchanged', 'Effect': 'Allow', 'Principal': {'AWS': f'arn:aws:iam::{ACCOUNT}:root'}, 'Action': 'kms:*', 'Resource': '*'},
            {'Sid': 'DocumentedSNSArchiveGrant', 'Effect': 'Allow', 'Principal': {'Service': 'sns.amazonaws.com'}, 'Action': ['kms:Decrypt','kms:GenerateDataKey'], 'Resource': '*'}]
    if denied:
        rows.append({'Sid': 'ExplicitSNSDecryptDeny', 'Effect': 'Deny', 'Principal': {'Service': 'sns.amazonaws.com'}, 'Action': 'kms:Decrypt', 'Resource': '*'})
    return json.dumps({'Version':'2012-10-17','Statement':rows})

def create_case(name, denied):
    c = {'name': name, 'deny_before_first_publication': denied}
    CASES.append(c)
    c['topic'] = call(name+'-create-topic','sns','create-topic',{'Name':PREFIX+'-'+name+'.fifo','Attributes':{'FifoTopic':'true','ArchivePolicy':'{"MessageRetentionPeriod":1}'}})['TopicArn']
    key = call(name+'-create-key','kms','create-key',{'Description':PREFIX+'-'+name,'Policy':policy(denied),'Tags':[{'TagKey':'stackd-probe','TagValue':PREFIX}]})['KeyMetadata']
    c['key'] = key['KeyId']
    c['key_arn'] = key['Arn']
    save()
    call(name+'-configure-encryption','sns','set-topic-attributes',{'TopicArn':c['topic'],'AttributeName':'KmsMasterKeyId','AttributeValue':c['key']})
    c['archive_start'] = call(name+'-archive-attributes','sns','get-topic-attributes',{'TopicArn':c['topic']})['Attributes']['BeginningArchiveTime']
    return c

def destination(c, label, replay):
    label=c['name']+'-'+label
    q=call(label+'-queue','sqs','create-queue',{'QueueName':PREFIX+'-'+label})['QueueUrl']
    QUEUES.append(q)
    save()
    arn=call(label+'-queue-arn','sqs','get-queue-attributes',{'QueueUrl':q,'AttributeNames':['QueueArn']})['Attributes']['QueueArn']
    p={'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'sns.amazonaws.com'},'Action':'sqs:SendMessage','Resource':arn,'Condition':{'ArnEquals':{'aws:SourceArn':c['topic']}}}]}
    call(label+'-queue-policy','sqs','set-queue-attributes',{'QueueUrl':q,'Attributes':{'Policy':json.dumps(p)}})
    inp={'TopicArn':c['topic'],'Protocol':'sqs','Endpoint':arn,'ReturnSubscriptionArn':True}
    if replay:
        inp['Attributes']={'ReplayPolicy':json.dumps({'PointType':'Timestamp','StartingPoint':c['archive_start']})}
    sub=call(label+'-subscribe','sns','subscribe',inp)['SubscriptionArn']
    SUBS.append(sub)
    save()
    return q,sub

def receive(c,label,q,sub,seconds=75):
    start=stamp()
    until_time=time.monotonic()+seconds
    matched=False
    while time.monotonic()<until_time:
        check()
        out=call(c['name']+'-'+label+'-receive','sqs','receive-message',{'QueueUrl':q,'WaitTimeSeconds':20,'MaxNumberOfMessages':10,'MessageSystemAttributeNames':['All'],'MessageAttributeNames':['All']})
        for msg in out.get('Messages',[]):
            retained={k:v for k,v in msg.items() if k!='ReceiptHandle'}
            body=json.loads(msg['Body'])
            is_match=body.get('MessageId')==c['publication']['MessageId'] and body.get('Message')==c['message']
            DATA['receipts'].append({'label':c['name']+'-'+label,'observed':stamp(),'queue':q,'subscription':sub,'matches_original_publication':is_match,'message':retained})
            matched = matched or is_match
            call(c['name']+'-'+label+'-delete-receipt','sqs','delete-message',{'QueueUrl':q,'ReceiptHandle':msg['ReceiptHandle']})
        if matched:
            break
    attrs=call(c['name']+'-'+label+'-status','sns','get-subscription-attributes',{'SubscriptionArn':sub}).get('Attributes',{})
    DATA['windows'].append({'label':c['name']+'-'+label,'start':start,'end':stamp(),'receipt_observed':matched,'ReplayStatus':attrs.get('ReplayStatus')})
    save()
    return matched

def replay(c,label):
    q,sub=destination(c,label,True)
    return receive(c,label,q,sub)

def trail(label):
    for c in CASES:
        if 'key_arn' not in c:
            continue
        call(c['name']+'-'+label,'cloudtrail','lookup-events',{'LookupAttributes':[{'AttributeKey':'ResourceName','AttributeValue':c['key_arn']}],'StartTime':DATA['started'],'EndTime':stamp()},strict=False,paginate=True)

def cleanup_call(*args,**kwargs):
    try:
        return call(*args,**kwargs,strict=False,cleanup=True)
    except Exception as exc:
        DATA.setdefault('cleanup_transport_errors',[]).append({'label':args[0],'error':str(exc),'observed':stamp()})
        save()
        return {}

try:
    identity=call('identity','sts','get-caller-identity')
    if identity.get('Account')!=ACCOUNT or identity.get('Arn')!=f'arn:aws:iam::{ACCOUNT}:user/Delegated':
        raise RuntimeError('Unexpected identity; refusing resource creation')
    print('ArchiveCold identity confirmed',flush=True)
    for name,denied in [('baseline',False),('pre-deny',True)]:
        c=create_case(name,denied)
        q,sub=destination(c,'live',False)
        c['message']='original encrypted archive '+name+' '+PREFIX
        c['publication']=call(name+'-publish-original','sns','publish',{'TopicArn':c['topic'],'Message':c['message'],'MessageGroupId':'group','MessageDeduplicationId':uuid.uuid4().hex})
        save()
        c['live_receipt']=receive(c,'live',q,sub)
        c['initial_replay_receipt']=replay(c,'initial-replay')
    c=CASES[0]
    if not c['initial_replay_receipt']:
        raise RuntimeError('No positive documented-grant replay baseline')
    call('baseline-add-explicit-deny','kms','put-key-policy',{'KeyId':c['key'],'PolicyName':'default','Policy':policy(True)})
    c['warm_explicit_deny_receipt']=replay(c,'warm-explicit-deny')
    print('ArchiveCold warm phase complete; idle until eight minutes',flush=True)
    until(480,'eight-minute-idle')
    trail('eight-minute-cloudtrail')
    for c in CASES:
        c['eight_minute_deny_receipt']=replay(c,'eight-minute-deny')
        call(c['name']+'-disable-original-key','kms','disable-key',{'KeyId':c['key']})
        call(c['name']+'-verify-disabled-key','kms','describe-key',{'KeyId':c['key']})
    print('ArchiveCold original keys disabled; idle until twenty minutes',flush=True)
    until(1200,'twenty-minute-idle')
    for c in CASES:
        c['twenty_minute_disabled_receipt']=replay(c,'twenty-minute-disabled')
    trail('twenty-minute-cloudtrail')
    for c in CASES:
        call(c['name']+'-enable-original-key','kms','enable-key',{'KeyId':c['key']})
        call(c['name']+'-restore-documented-policy','kms','put-key-policy',{'KeyId':c['key'],'PolicyName':'default','Policy':policy(False)})
        call(c['name']+'-verify-restored-policy','kms','get-key-policy',{'KeyId':c['key'],'PolicyName':'default'})
        call(c['name']+'-verify-enabled-key','kms','describe-key',{'KeyId':c['key']})
        c['restored_original_receipt']=replay(c,'restored-original')
    print('ArchiveCold restored phase complete; awaiting CloudTrail propagation',flush=True)
    until(1620,'final-cloudtrail-propagation')
    trail('final-cloudtrail')
except Exception as exc:
    DATA['capture_error']=str(exc)
    DATA['capture_traceback']=traceback.format_exc()
    print(DATA['capture_traceback'],flush=True)
finally:
    DATA['owned_resources']={'topics':[c.get('topic') for c in CASES], 'keys':[c.get('key') for c in CASES], 'queues':QUEUES,'subscriptions':SUBS,'functions':[],'roles':[],'log_groups':[]}
    save()
    for sub in reversed(SUBS):
        cleanup_call('unsubscribe','sns','unsubscribe',{'SubscriptionArn':sub})
        cleanup_call('subscription-absence','sns','get-subscription-attributes',{'SubscriptionArn':sub})
    for c in CASES:
        if 'topic' in c:
            cleanup_call(c['name']+'-disable-archive','sns','set-topic-attributes',{'TopicArn':c['topic'],'AttributeName':'ArchivePolicy','AttributeValue':'{}'})
            cleanup_call(c['name']+'-delete-topic','sns','delete-topic',{'TopicArn':c['topic']})
            cleanup_call(c['name']+'-topic-absence','sns','get-topic-attributes',{'TopicArn':c['topic']})
    for q in reversed(QUEUES):
        cleanup_call('delete-queue','sqs','delete-queue',{'QueueUrl':q})
        cleanup_call('queue-absence','sqs','get-queue-attributes',{'QueueUrl':q,'AttributeNames':['QueueArn']})
    for c in CASES:
        if 'key' in c:
            cleanup_call(c['name']+'-schedule-key-deletion','kms','schedule-key-deletion',{'KeyId':c['key'],'PendingWindowInDays':7})
            c['residual_key']=cleanup_call(c['name']+'-verify-key-pending-deletion','kms','describe-key',{'KeyId':c['key']}).get('KeyMetadata')
    time.sleep(65)
    for q in QUEUES:
        cleanup_call('independent-queue-absence','sqs','get-queue-attributes',{'QueueUrl':q,'AttributeNames':['QueueArn']})
    cleanup_call('independent-prefix-queue-list','sqs','list-queues',{'QueueNamePrefix':PREFIX},paginate=True)
    for c in CASES:
        if 'topic' in c:
            cleanup_call(c['name']+'-independent-topic-absence','sns','get-topic-attributes',{'TopicArn':c['topic']})
    DATA['capture_program']=Path(__file__).read_text()
    DATA['finished']=stamp()
    save()
    print(json.dumps({'fixture':str(OUTPUT),'receipts':len(DATA['receipts']),'error':DATA.get('capture_error'),'keys':[c.get('key') for c in CASES]}),flush=True)

